import { format, resolveConfig } from 'prettier'
import type { AbilityPresentationProjection } from '@black-whale/nen-engine'

const HEADER = `// Generated by \`pnpm --filter @black-whale/canon-compiler compile:hatsu\`.
// Do not edit: the action wheel, plans and component keys come from ability modules.

import type { AbilityPresentationProjection } from '@black-whale/nen-engine'
`

export async function emitAbilityPresentations(
  presentations: readonly AbilityPresentationProjection[],
  filepath: string,
): Promise<string> {
  // One JSON string keeps TypeScript from inferring and checking a 25k-line
  // object literal on every Svelte typecheck. The cast is safe because the
  // value was produced from the typed projections immediately above.
  const payload = JSON.stringify(presentations)
  const source = `${HEADER}
export const ABILITY_PRESENTATIONS = JSON.parse(${JSON.stringify(
    payload,
  )}) as AbilityPresentationProjection[]
`
  const config = await resolveConfig(filepath)
  return format(source, { ...config, filepath })
}
